#helpPanel {
  position: absolute;
  top: 50px;
  right: 10px;
  width: 200px;
  padding: 10px;
  background-color: white;
  border: 1px solid #ccc;
  border-radius: 5px;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

document.getElementById('help').addEventListener('click', () => {
  const helpPanel = document.getElementById('helpPanel');
  if (helpPanel.style.display === 'none') {
    helpPanel.style.display = 'block';
  } else {
    helpPanel.style.display = 'none';
  }
});

document.addEventListener('DOMContentLoaded', () => {
  const controlsList = document.getElementById('controlsList');
  const controls = [
    { key: 'Space', action: 'Flap' },
    { key: 'ArrowUp', action: 'Move Up' },
    { key: 'ArrowDown', action: 'Move Down' },
    { key: 'ArrowLeft', action: 'Move Left' },
    { key: 'ArrowRight', action: 'Move Right' },
    { key: 'Click', action: 'Interact' }
  ];

  controls.forEach(control => {
    const li = document.createElement('li');
    li.textContent = `${control.key}: ${control.action}`;
    controlsList.appendChild(li);
  });
});

